   426→							onQuestionsChange={setQuestions}
   427→							activeDragItem={activeDragItem}
   428→							overId={overId}
   429→							justReordered={justReordered}
   430→						/>
   431→
   432→						{/* Right Properties Panel - Responsive */}
   433→						{activeTab === "build" && (
