	useEffect(() => {
		setQuestions(initialQuestions);
	}, [initialQuestions]);

	// Reset justReordered after animations complete
	useEffect(() => {
		if (justReordered) {
			const timer = setTimeout(() => {
				setJustReordered(false);
			}, 300); // Match spring animation duration
			return () => clearTimeout(timer);
		}
	}, [justReordered]);

